import * as error from 'lib0/error'
import * as map from 'lib0/map'
import * as math from 'lib0/math'
import * as logging from 'lib0/logging'
import { callAll } from 'lib0/function'

import { ContentFormat } from '../structs/Item.js'
import { getStateVector } from './StructStore.js'
import { callEventHandlerListeners } from './EventHandler.js'
import { createIdSet, iterateStructsByIdSet } from './ids.js'
import { GC } from '../structs/GC.js'
import { YEvent } from './YEvent.js'
import { writeUpdateMessageFromTransaction } from './encoding-helpers.js'
import { UpdateEncoderV1, UpdateEncoderV2 } from './UpdateEncoder.js'
import { findIndexSS, updateCurrentFormats, cleanupFormattingGap, tryGcDeleteSet, tryMerge, tryToMergeWithLefts, cleanupContextlessFormattingGap } from './transaction-helpers.js'
import * as random from 'lib0/random'

export const generateNewClientId = random.uint53

/**
 * A transaction is created for every change on the Yjs model. It is possible
 * to bundle changes on the Yjs model in a single transaction to
 * minimize the number on messages sent and the number of observer calls.
 * If possible the user of this library should bundle as many changes as
 * possible. Here is an example to illustrate the advantages of bundling:
 *
 * @example
 * const ydoc = new Y.Doc()
 * const map = ydoc.get('map')
 * // Log content when change is triggered
 * map.observe(() => {
 *   console.log('change triggered')
 * })
 * // Each change on the map type triggers a log message:
 * map.setAttr('a', 0) // => "change triggered"
 * map.setAttr('b', 0) // => "change triggered"
 * // When put in a transaction, it will trigger the log after the transaction:
 * ydoc.transact(() => {
 *   map.setAttr('a', 1)
 *   map.setAttr('b', 1)
 * }) // => "change triggered"
 *
 * @public
 */
export class Transaction {
  /**
   * @param {Doc} doc
   * @param {any} origin
   * @param {boolean} local
   */
  constructor (doc, origin, local) {
    /**
     * The Yjs instance.
     * @type {Doc}
     */
    this.doc = doc
    /**
     * Describes the set of deleted items by ids
     */
    this.deleteSet = createIdSet()
    /**
     * Describes the set of items that are cleaned up / deleted by ids. It is a subset of
     * this.deleteSet
     */
    this.cleanUps = createIdSet()
    /**
     * Describes the set of inserted items by ids
     */
    this.insertSet = createIdSet()
    /**
     * Holds the state before the transaction started.
     * @type {Map<Number,Number>?}
     */
    this._beforeState = null
    /**
     * Holds the state after the transaction.
     * @type {Map<Number,Number>?}
     */
    this._afterState = null
    /**
     * All types that were directly modified (property added or child
     * inserted/deleted). New types are not included in this Set.
     * Maps from type to parentSubs (`item.parentSub = null` for YArray)
     * @type {Map<YNode,Set<String|null>>}
     */
    this.changed = new Map()
    /**
     * Stores the events for the types that observe also child elements.
     * It is mainly used by `observeDeep`.
     * @type {Map<YNode,Array<YEvent<any>>>}
     */
    this.changedParentTypes = new Map()
    /**
     * @type {Array<AbstractStruct>}
     */
    this._mergeStructs = []
    /**
     * @type {any}
     */
    this.origin = origin
    /**
     * Stores meta information on the transaction
     * @type {Map<any,any>}
     */
    this.meta = new Map()
    /**
     * Whether this change originates from this doc.
     * @type {boolean}
     */
    this.local = local
    /**
     * @type {Set<Doc>}
     */
    this.subdocsAdded = new Set()
    /**
     * @type {Set<Doc>}
     */
    this.subdocsRemoved = new Set()
    /**
     * @type {Set<Doc>}
     */
    this.subdocsLoaded = new Set()
    /**
     * @type {boolean}
     */
    this._needFormattingCleanup = false
    this._done = false
  }

  /**
   * Holds the state before the transaction started.
   *
   * @deprecated
   * @type {Map<Number,Number>}
   */
  get beforeState () {
    if (this._beforeState == null) {
      const sv = getStateVector(this.doc.store)
      this.insertSet.clients.forEach((ranges, client) => {
        sv.set(client, ranges.getIds()[0].clock)
      })
      this._beforeState = sv
    }
    return this._beforeState
  }

  /**
   * Holds the state after the transaction.
   *
   * @deprecated
   * @type {Map<Number,Number>}
   */
  get afterState () {
    if (!this._done) error.unexpectedCase()
    if (this._afterState == null) {
      const sv = getStateVector(this.doc.store)
      this.insertSet.clients.forEach((_ranges, client) => {
        const ranges = _ranges.getIds()
        const d = ranges[ranges.length - 1]
        sv.set(client, d.clock + d.len)
      })
      this._afterState = sv
    }
    return this._afterState
  }
}

/**
 * This function is experimental and subject to change / be removed.
 *
 * Ideally, we don't need this function at all. Formats should be cleaned up
 * automatically after each change. This function iterates twice over the complete YText type
 * and removes unnecessary formats. This is also helpful for testing.
 *
 * This function won't be exported anymore as soon as there is confidence that the YText type works as intended.
 *
 * @param {YNode} type
 * @return {number} How many formats have been cleaned up.
 */
export const cleanupYTextFormatting = type => {
  if (!type.doc?.cleanupFormatting) return 0
  let res = 0
  transact(/** @type {Doc} */ (type.doc), transaction => {
    let start = /** @type {Item} */ (type._start)
    let end = type._start
    let startFormats = map.create()
    const currentFormats = map.copy(startFormats)
    while (end) {
      if (end.deleted === false) {
        switch (end.content.constructor) {
          case ContentFormat:
            updateCurrentFormats(currentFormats, /** @type {ContentFormat} */ (end.content))
            break
          default:
            res += cleanupFormattingGap(transaction, start, end, startFormats, currentFormats)
            startFormats = map.copy(currentFormats)
            start = end
            break
        }
      }
      end = end.right
    }
  })
  return res
}

/**
 * @param {Array<Transaction>} transactionCleanups
 * @param {number} i
 */
const cleanupTransactions = (transactionCleanups, i) => {
  if (i < transactionCleanups.length) {
    const transaction = transactionCleanups[i]
    transaction._done = true
    const doc = transaction.doc
    const store = doc.store
    const ds = transaction.deleteSet
    const mergeStructs = transaction._mergeStructs
    // insertIntoIdSet(store.ds, ds)
    try {
      doc.emit('beforeObserverCalls', [transaction, doc])
      /**
       * An array of event callbacks.
       *
       * Each callback is called even if the other ones throw errors.
       *
       * @type {Array<function():void>}
       */
      const fs = []
      // observe events on changed types. Deleted types are included: `callTypeObservers` tracks
      // the event in `changedParentTypes` unconditionally (so changes inside a deleted type — e.g.
      // a suggestion-deleted tombstone that a custom renderer still renders — bubble to live
      // ancestors) and decides itself whether the type's own observers fire.
      transaction.changed.forEach((subs, itemtype) =>
        fs.push(() => {
          itemtype._callObserver(transaction, subs)
        })
      )
      fs.push(() => {
        // deep observe events + the RDT `'delta'` channel. `changedParentTypes` holds the changed
        // type AND all of its ancestors, so both `observeDeep` and `'delta'` bubble identically.
        transaction.changedParentTypes.forEach((events, type) => {
          // We need to think about the possibility that the user transforms the
          // Y.Doc in the event.
          // Deleted types are tracked (so changes inside them bubble to live ancestors) but fire
          // only while something still renders them — i.e. they have a renderer attached.
          if (type._item !== null && type._item.deleted && type._renderer === null) return
          const hasDeep = type._dEH.l.length > 0
          const hasDeltaListeners = (type._observers.get('delta')?.size ?? 0) > 0
          const maintaining = type._delta !== null
          if (!hasDeep && !hasDeltaListeners && !maintaining) return
          /**
           * @type {YEvent<any>}
           */
          const deepEventHandler = events.find(event => event.target === type) || new YEvent(type, transaction, new Set(null))
          if (hasDeep) {
            callEventHandlerListeners(type._dEH, deepEventHandler, transaction)
          }
          if (hasDeltaListeners || maintaining) {
            // the type-rooted deep delta of this transaction (a nested `modify` chain for ancestors)
            const change = /** @type {any} */ (deepEventHandler.getDelta({ renderer: type._renderer, deep: true }).done())
            // a base-renderer type doesn't render deleted content, so a change that happened
            // entirely inside a deleted subtree renders to an empty delta — don't emit those no-ops
            if (!change.isEmpty()) {
              type._delta?.apply(change) // keep the cache current (incl. ancestors and diff-renderer attributions) — builder API only, see the YNode._delta fingerprint-memo invariant
              if (hasDeltaListeners) type.emit('delta', [change, transaction.origin])
            }
          }
        })
      })
      fs.push(() => doc.emit('afterTransaction', [transaction, doc]))
      callAll(fs, [])
      if (transaction._needFormattingCleanup && doc.cleanupFormatting) {
        cleanupYTextAfterTransaction(transaction)
      }
    } finally {
      // Replace deleted items with ItemDeleted / GC.
      // This is where content is actually remove from the Yjs Doc.
      if (doc.gc) {
        tryGcDeleteSet(transaction, ds, doc.gcFilter)
      }
      tryMerge(ds, store)

      // on all affected store.clients props, try to merge
      transaction.insertSet.clients.forEach((ids, client) => {
        const firstClock = ids.getIds()[0].clock
        const structs = /** @type {Array<GC|Item>} */ (store.clients.get(client))
        // we iterate from right to left so we can safely remove entries
        const firstChangePos = math.max(findIndexSS(structs, firstClock), 1)
        for (let i = structs.length - 1; i >= firstChangePos;) {
          i -= 1 + tryToMergeWithLefts(structs, i)
        }
      })
      // try to merge mergeStructs
      // @todo: it makes more sense to transform mergeStructs to a DS, sort it, and merge from right to left
      //        but at the moment DS does not handle duplicates
      for (let i = mergeStructs.length - 1; i >= 0; i--) {
        const { client, clock } = mergeStructs[i].id
        const structs = /** @type {Array<GC|Item>} */ (store.clients.get(client))
        const replacedStructPos = findIndexSS(structs, clock)
        if (replacedStructPos + 1 < structs.length) {
          if (tryToMergeWithLefts(structs, replacedStructPos + 1) > 1) {
            continue // no need to perform next check, both are already merged
          }
        }
        if (replacedStructPos > 0) {
          tryToMergeWithLefts(structs, replacedStructPos)
        }
      }
      if (!transaction.local && transaction.insertSet.clients.has(doc.clientID)) {
        logging.print(logging.ORANGE, logging.BOLD, '[yjs] ', logging.UNBOLD, logging.RED, 'Changed the client-id because another client seems to be using it.')
        doc.clientID = generateNewClientId()
      }
      // @todo Merge all the transactions into one and provide send the data as a single update message
      doc.emit('afterTransactionCleanup', [transaction, doc])
      if (doc._observers.has('update')) {
        const encoder = new UpdateEncoderV1()
        const hasContent = writeUpdateMessageFromTransaction(encoder, transaction)
        if (hasContent) {
          doc.emit('update', [encoder.toUint8Array(), transaction.origin, doc, transaction])
        }
      }
      if (doc._observers.has('updateV2')) {
        const encoder = new UpdateEncoderV2()
        const hasContent = writeUpdateMessageFromTransaction(encoder, transaction)
        if (hasContent) {
          doc.emit('updateV2', [encoder.toUint8Array(), transaction.origin, doc, transaction])
        }
      }
      const { subdocsAdded, subdocsLoaded, subdocsRemoved } = transaction
      if (subdocsAdded.size > 0 || subdocsRemoved.size > 0 || subdocsLoaded.size > 0) {
        subdocsAdded.forEach(subdoc => {
          subdoc.clientID = doc.clientID
          if (subdoc.collectionid == null) {
            subdoc.collectionid = doc.collectionid
          }
          doc.subdocs.add(subdoc)
        })
        subdocsRemoved.forEach(subdoc => doc.subdocs.delete(subdoc))
        doc.emit('subdocs', [{ loaded: subdocsLoaded, added: subdocsAdded, removed: subdocsRemoved }, doc, transaction])
        subdocsRemoved.forEach(subdoc => subdoc.destroy())
      }

      if (transactionCleanups.length <= i + 1) {
        doc._transactionCleanups = []
        doc.emit('afterAllTransactions', [doc, transactionCleanups])
      } else {
        cleanupTransactions(transactionCleanups, i + 1)
      }
    }
  }
}

/**
 * This will be called by the transaction once the event handlers are called to potentially cleanup
 * formats.
 *
 * @param {Transaction} transaction
 */
export const cleanupYTextAfterTransaction = transaction => {
  /**
   * @type {Set<YNode>}
   */
  const needFullCleanup = new Set()
  // check if another formatting item was inserted
  const doc = transaction.doc
  iterateStructsByIdSet(transaction, transaction.insertSet, (item) => {
    if (
      !item.deleted && /** @type {Item} */ (item).content.constructor === ContentFormat && item.constructor !== GC
    ) {
      needFullCleanup.add(/** @type {any} */ (item).parent)
    }
  })
  // cleanup in a new transaction
  transact(doc, (t) => {
    iterateStructsByIdSet(transaction, transaction.deleteSet, item => {
      if (item instanceof GC || !(/** @type {YNode} */ (item.parent)._hasFormatting) || needFullCleanup.has(/** @type {YNode} */ (item.parent))) {
        return
      }
      const parent = /** @type {YNode} */ (item.parent)
      if (item.content.constructor === ContentFormat) {
        needFullCleanup.add(parent)
      } else {
        // If no format was inserted or deleted, we can make due with contextless
        // formatting cleanups.
        // Contextless: it is not necessary to compute currentFormats for the affected position.
        cleanupContextlessFormattingGap(t, item)
      }
    })
    // If a formatting item was inserted, we simply clean the whole type.
    // We need to compute currentFormats for the current position anyway.
    for (const yText of needFullCleanup) {
      cleanupYTextFormatting(yText)
    }
  })
}

/**
 * Implements the functionality of `y.transact(()=>{..})`
 *
 * @template T
 * @param {Doc} doc
 * @param {function(Transaction):T} f
 * @param {any} [origin=true]
 * @param {boolean} [local=true]
 * @return {T}
 *
 * @function
 */
export const transact = (doc, f, origin = null, local = true) => {
  const transactionCleanups = doc._transactionCleanups
  let initialCall = false
  /**
   * @type {any}
   */
  let result = null
  if (doc._transaction === null) {
    initialCall = true
    doc._transaction = new Transaction(doc, origin, local)
    transactionCleanups.push(doc._transaction)
    if (transactionCleanups.length === 1) {
      doc.emit('beforeAllTransactions', [doc])
    }
    doc.emit('beforeTransaction', [doc._transaction, doc])
  }
  try {
    result = f(doc._transaction)
  } finally {
    if (initialCall) {
      const finishCleanup = doc._transaction === transactionCleanups[0]
      doc._transaction = null
      if (finishCleanup) {
        // The first transaction ended, now process observer calls.
        // Observer call may create new transactions for which we need to call the observers and do cleanup.
        // We don't want to nest these calls, so we execute these calls one after
        // another.
        // Also we need to ensure that all cleanups are called, even if the
        // observes throw errors.
        // This file is full of hacky try {} finally {} blocks to ensure that an
        // event can throw errors and also that the cleanup is called.
        cleanupTransactions(transactionCleanups, 0)
      }
    }
  }
  return result
}

import { describe, it, expect, vi, beforeEach } from 'vitest'

vi.mock('@/utils/storage', () => ({
  saveKeys: vi.fn().mockResolvedValue('sync'),
  loadKeys: vi.fn().mockResolvedValue(null),
}))

import { useUndoRedo } from '../src/composables/useUndoRedo'
import { ref } from 'vue'
import type { KeySetting } from '../src/utils/url-matching'

function makeKey(overrides: Partial<KeySetting> = {}): KeySetting {
  return {
    id: Math.random().toString(36).slice(2),
    key: 'ctrl+a',
    action: 'newtab',
    enabled: true,
    sites: '',
    sitesArray: [''],
    ...overrides,
  } as KeySetting
}

describe('useUndoRedo', () => {
  let keys: ReturnType<typeof ref<KeySetting[]>>

  beforeEach(() => {
    keys = ref<KeySetting[]>([])
    const { init, undoStack, redoStack, lastActionLabel } = useUndoRedo()
    // Reset state
    undoStack.value = []
    redoStack.value = []
    lastActionLabel.value = ''
    init(keys)
  })

  describe('pushUndo', () => {
    it('snapshots the current keys state', () => {
      const { pushUndo, undoStack } = useUndoRedo()
      keys.value = [makeKey({ key: 'ctrl+a' })]
      pushUndo('test action')
      expect(undoStack.value).toHaveLength(1)
      expect(undoStack.value[0]).toHaveLength(1)
      expect(undoStack.value[0][0].key).toBe('ctrl+a')
    })

    it('creates deep clones (modifying keys does not affect stack)', () => {
      const { pushUndo, undoStack } = useUndoRedo()
      keys.value = [makeKey({ key: 'ctrl+a' })]
      pushUndo('test')
      keys.value[0].key = 'ctrl+b'
      expect(undoStack.value[0][0].key).toBe('ctrl+a')
    })

    it('clears redo stack on new action', () => {
      const { pushUndo, redoStack } = useUndoRedo()
      // Simulate some redo state
      redoStack.value = [[makeKey()]]
      pushUndo('new action')
      expect(redoStack.value).toHaveLength(0)
    })

    it('sets lastActionLabel', () => {
      const { pushUndo, lastActionLabel } = useUndoRedo()
      pushUndo('Shortcut deleted')
      expect(lastActionLabel.value).toBe('Shortcut deleted')
    })

    it('respects MAX_UNDO_DEPTH', () => {
      const { pushUndo, undoStack, MAX_UNDO_DEPTH } = useUndoRedo()
      for (let i = 0; i < MAX_UNDO_DEPTH + 5; i++) {
        keys.value = [makeKey({ key: `ctrl+${i}` })]
        pushUndo(`action ${i}`)
      }
      expect(undoStack.value).toHaveLength(MAX_UNDO_DEPTH)
      // Oldest entries should have been shifted off
      expect(undoStack.value[0][0].key).toBe('ctrl+5')
    })
  })

  describe('undo', () => {
    it('restores previous state', async () => {
      const { pushUndo, undo } = useUndoRedo()
      keys.value = [makeKey({ key: 'ctrl+a' })]
      pushUndo('before delete')
      keys.value = [] // simulate deletion
      await undo()
      expect(keys.value).toHaveLength(1)
      expect(keys.value[0].key).toBe('ctrl+a')
    })

    it('pushes current state to redo stack', async () => {
      const { pushUndo, undo, redoStack } = useUndoRedo()
      keys.value = [makeKey({ key: 'ctrl+a' })]
      pushUndo('test')
      keys.value = [makeKey({ key: 'ctrl+b' })]
      await undo()
      expect(redoStack.value).toHaveLength(1)
      expect(redoStack.value[0][0].key).toBe('ctrl+b')
    })

    it('is a no-op when undo stack is empty', async () => {
      const { undo, undoStack } = useUndoRedo()
      keys.value = [makeKey({ key: 'ctrl+a' })]
      await undo()
      expect(keys.value).toHaveLength(1)
      expect(keys.value[0].key).toBe('ctrl+a')
      expect(undoStack.value).toHaveLength(0)
    })

    it('calls saveKeys after undo', async () => {
      const { saveKeys } = await import('../src/utils/storage')
      const { pushUndo, undo } = useUndoRedo()
      keys.value = [makeKey()]
      pushUndo('test')
      keys.value = []
      await undo()
      expect(saveKeys).toHaveBeenCalled()
    })
  })

  describe('redo', () => {
    it('restores undone state', async () => {
      const { pushUndo, undo, redo } = useUndoRedo()
      keys.value = [makeKey({ key: 'ctrl+a' })]
      pushUndo('test')
      keys.value = [makeKey({ key: 'ctrl+b' })]
      await undo()
      expect(keys.value[0].key).toBe('ctrl+a')
      await redo()
      expect(keys.value[0].key).toBe('ctrl+b')
    })

    it('is a no-op when redo stack is empty', async () => {
      const { redo, redoStack } = useUndoRedo()
      keys.value = [makeKey({ key: 'ctrl+a' })]
      await redo()
      expect(keys.value).toHaveLength(1)
      expect(keys.value[0].key).toBe('ctrl+a')
      expect(redoStack.value).toHaveLength(0)
    })

    it('pushes current state to undo stack', async () => {
      const { pushUndo, undo, redo, undoStack } = useUndoRedo()
      keys.value = [makeKey({ key: 'ctrl+a' })]
      pushUndo('test')
      keys.value = []
      await undo()
      await redo()
      expect(undoStack.value.length).toBeGreaterThan(0)
    })
  })

  describe('canUndo / canRedo', () => {
    it('canUndo is false initially', () => {
      const { canUndo } = useUndoRedo()
      expect(canUndo.value).toBe(false)
    })

    it('canRedo is false initially', () => {
      const { canRedo } = useUndoRedo()
      expect(canRedo.value).toBe(false)
    })

    it('canUndo becomes true after pushUndo', () => {
      const { pushUndo, canUndo } = useUndoRedo()
      pushUndo('test')
      expect(canUndo.value).toBe(true)
    })

    it('canRedo becomes true after undo', async () => {
      const { pushUndo, undo, canRedo } = useUndoRedo()
      keys.value = [makeKey()]
      pushUndo('test')
      keys.value = []
      await undo()
      expect(canRedo.value).toBe(true)
    })

    it('canRedo becomes false after new pushUndo', async () => {
      const { pushUndo, undo, canRedo } = useUndoRedo()
      keys.value = [makeKey()]
      pushUndo('test')
      keys.value = []
      await undo()
      expect(canRedo.value).toBe(true)
      pushUndo('new action')
      expect(canRedo.value).toBe(false)
    })
  })

  describe('multiple undo/redo cycles', () => {
    it('handles three sequential undos', async () => {
      const { pushUndo, undo } = useUndoRedo()
      keys.value = [makeKey({ key: 'ctrl+1' })]
      pushUndo('step 1')
      keys.value = [makeKey({ key: 'ctrl+2' })]
      pushUndo('step 2')
      keys.value = [makeKey({ key: 'ctrl+3' })]
      pushUndo('step 3')
      keys.value = []

      await undo() // back to step 3
      expect(keys.value).toHaveLength(1)
      expect(keys.value[0].key).toBe('ctrl+3')

      await undo() // back to step 2
      expect(keys.value[0].key).toBe('ctrl+2')

      await undo() // back to step 1
      expect(keys.value[0].key).toBe('ctrl+1')
    })

    it('handles undo then redo then undo', async () => {
      const { pushUndo, undo, redo } = useUndoRedo()
      keys.value = [makeKey({ key: 'ctrl+a' })]
      pushUndo('step 1')
      keys.value = [makeKey({ key: 'ctrl+b' })]

      await undo()
      expect(keys.value[0].key).toBe('ctrl+a')

      await redo()
      expect(keys.value[0].key).toBe('ctrl+b')

      await undo()
      expect(keys.value[0].key).toBe('ctrl+a')
    })
  })
})

